1	import React, { useState, useEffect, useCallback } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { supabase } from "@/integrations/supabase/client";
4	import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
5	import { Button } from "@/components/ui/button";
6	import { Separator } from "@/components/ui/separator";
7	import { Bell, CheckCircle2, AlertCircle, FileText, Coins, Info, CheckCheck, ArrowRight, MessageSquare, CheckSquare, UserPlus } from "lucide-react";
8	import { cn } from "@/lib/utils";
9	import { formatDistanceToNow } from "date-fns";
10	
11	// ─── Types ──────────────────────────────────────────────────────────────────
12	
13	interface Notification {
14	  id: string;
15	  type: "ranking_complete" | "ranking_failed" | "credits_low" | "credits_added" | "system"
16	    | "stage_changed" | "note_added" | "task_assigned" | "task_completed" | "member_joined";
17	  title: string;
18	  message: string;
19	  read: boolean;
20	  created_at: string;
21	  metadata?: Record<string, any>;
22	}
23	
24	const ICON_MAP: Record<Notification["type"], { icon: typeof Bell; color: string; bg: string }> = {
25	  ranking_complete: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
26	  ranking_failed: { icon: AlertCircle, color: "text-destructive", bg: "bg-destructive/10" },
27	  credits_low: { icon: Coins, color: "text-amber-600", bg: "bg-amber-100" },
28	  credits_added: { icon: Coins, color: "text-blue-600", bg: "bg-blue-100" },
29	  system: { icon: Info, color: "text-muted-foreground", bg: "bg-muted" },
30	  stage_changed: { icon: ArrowRight, color: "text-violet-600", bg: "bg-violet-100" },
31	  note_added: { icon: MessageSquare, color: "text-blue-600", bg: "bg-blue-100" },
32	  task_assigned: { icon: CheckSquare, color: "text-orange-600", bg: "bg-orange-100" },
33	  task_completed: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
34	  member_joined: { icon: UserPlus, color: "text-primary", bg: "bg-primary/10" },
35	};
36	
37	// ─── Component ──────────────────────────────────────────────────────────────
38	
39	const NotificationBell = () => {
40	  const { user } = useAuth();
41	  const [open, setOpen] = useState(false);
42	  const [notifications, setNotifications] = useState<Notification[]>([]);
43	  const [loading, setLoading] = useState(false);
44	
45	  const unreadCount = notifications.filter((n) => !n.read).length;
46	
47	  const fetchNotifications = useCallback(async () => {
48	    if (!user) return;
49	    setLoading(true);
50	    try {
51	      const { data } = await supabase
52	        .from("notifications")
53	        .select("id, type, title, message, read, created_at, metadata")
54	        .eq("user_id", user.id)
55	        .order("created_at", { ascending: false })
56	        .limit(20);
57	      if (data) setNotifications(data as Notification[]);
58	    } catch {
59	      // Silently fail — notifications are non-critical
60	    } finally {
61	      setLoading(false);
62	    }
63	  }, [user]);
64	
65	  // Initial fetch for badge count
66	  useEffect(() => {
67	    fetchNotifications();
68	  }, [fetchNotifications]);
69	
70	  // Refresh when popover opens
71	  useEffect(() => {
72	    if (open) fetchNotifications();
73	  }, [open, fetchNotifications]);
74	
75	  // Real-time subscription for new notifications
76	  useEffect(() => {
77	    if (!user) return;
78	
79	    const channel = supabase
80	      .channel("notifications")
81	      .on(
82	        "postgres_changes",
83	        {
84	          event: "INSERT",
85	          schema: "public",
86	          table: "notifications",
87	          filter: `user_id=eq.${user.id}`,
88	        },
89	        (payload) => {
90	          setNotifications((prev) => [payload.new as Notification, ...prev].slice(0, 20));
91	        }
92	      )
93	      .subscribe();
94	
95	    return () => {
96	      supabase.removeChannel(channel);
97	    };
98	  }, [user?.id]);
99	
100	  const markAsRead = async (id: string) => {
101	    setNotifications((prev) =>
102	      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
103	    );
104	    await supabase.from("notifications").update({ read: true }).eq("id", id);
105	  };
106	
107	  const markAllAsRead = async () => {
108	    if (unreadCount === 0) return;
109	    const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
110	    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
111	    await supabase.from("notifications").update({ read: true }).in("id", unreadIds);
112	  };
113	
114	  return (
115	    <Popover open={open} onOpenChange={setOpen}>
116	      <PopoverTrigger asChild>
117	        <button
118	          className="relative h-9 w-9 rounded-lg bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1"
119	          aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ""}`}
120	        >
121	          <Bell className="h-4 w-4" />
122	          {unreadCount > 0 && (
123	            <span className="absolute -top-0.5 -right-0.5 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground text-[10px] font-bold leading-none shadow-sm">
124	              {unreadCount > 99 ? "99+" : unreadCount}
125	            </span>
126	          )}
127	        </button>
128	      </PopoverTrigger>
129	
130	      <PopoverContent align="end" className="w-80 p-0">
131	        {/* Header */}
132	        <div className="flex items-center justify-between px-4 pt-3.5 pb-3">
133	          <h3 className="text-sm font-semibold text-foreground">Notifications</h3>
134	          {unreadCount > 0 && (
135	            <button
136	              onClick={markAllAsRead}
137	              className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:text-primary/80 transition-colors"
138	            >
139	              <CheckCheck className="h-3 w-3" />
140	              Mark all read
141	            </button>
142	          )}
143	        </div>
144	
145	        <Separator />
146	
147	        {/* Notification list */}
148	        <div className="max-h-[360px] overflow-y-auto">
149	          {loading && notifications.length === 0 ? (
150	            <div className="px-4 py-8 text-center">
151	              <div className="h-4 w-4 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
152	              <p className="text-xs text-muted-foreground mt-2">Loading...</p>
153	            </div>
154	          ) : notifications.length === 0 ? (
155	            <div className="px-4 py-10 text-center">
156	              <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
157	              <p className="text-sm text-muted-foreground">No notifications yet</p>
158	              <p className="text-xs text-muted-foreground/70 mt-0.5">
159	                We'll notify you about job rankings and updates.
160	              </p>
161	            </div>
162	          ) : (
163	            notifications.map((notification) => {
164	              const style = ICON_MAP[notification.type] ?? ICON_MAP.system;
165	              const Icon = style.icon;
166	
167	              return (
168	                <button
169	                  key={notification.id}
170	                  onClick={() => markAsRead(notification.id)}
171	                  className={cn(
172	                    "w-full text-left px-4 py-3 flex gap-3 hover:bg-muted/50 transition-colors border-b border-border last:border-0",
173	                    !notification.read && "bg-primary/[0.03]"
174	                  )}
175	                >
176	                  <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5", style.bg)}>
177	                    <Icon className={cn("h-4 w-4", style.color)} />
178	                  </div>
179	                  <div className="min-w-0 flex-1">
180	                    <div className="flex items-start justify-between gap-2">
181	                      <p className={cn("text-sm leading-tight truncate", !notification.read ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
182	                        {notification.title}
183	                      </p>
184	                      {!notification.read && (
185	                        <span className="h-2 w-2 rounded-full bg-primary shrink-0 mt-1.5" />
186	                      )}
187	                    </div>
188	                    <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">
189	                      {notification.message}
190	                    </p>
191	                    <p className="text-[10px] text-muted-foreground/60 mt-1">
192	                      {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true })}
193	                    </p>
194	                  </div>
195	                </button>
196	              );
197	            })
198	          )}
199	        </div>
200	      </PopoverContent>
201	    </Popover>
202	  );
203	};
204	
205	export default React.memo(NotificationBell);
206	
